sys_ux_data_broker_transform.script:
function transform(input) {
    // Corrected property name (addtional -> additional)
    var additionalKpiProperty = 'customwalk.properties';

    // Also try with the original spelling as fallback
    var fallbackPropertyName = 'customwalk.properties';

    // Initialize the result object with categories as separate arrays
    var result = {
        saas_integration: [],
        onpremises_integration: [],
        additional_publisher: [],
        publisher_ELP: [],
        //top_publisher_selection: [],
        //manual_data_import: [],
        // Add any other categories you might need
        implementation_kpis: [] // Keep this empty as requested
    };

    function fetchKPIs(propertyName) {
        var kpis = [];

        // Add debugging
        gs.log("Attempting to fetch property: " + propertyName);

        var propertyValue = gs.getProperty(propertyName);

        if (propertyValue) {
            gs.log("Successfully retrieved property value");
            try {
                // gs.log("Raw property value: " + propertyValue);
                kpis = JSON.parse(propertyValue);
                gs.log("Successfully parsed JSON data");
            } catch (e) {
                gs.log("Error parsing " + propertyName + ": " + e.message);
            }
        } else {
            gs.log("Property not found or empty: " + propertyName);
        }

        return kpis;
    }

    function processImplementationKPIs(data) {
        // gs.log("Processing implementation KPIs, data is array: " + Array.isArray(data));

        if (Array.isArray(data)) {
            // gs.log("Data array length: " + data.length);

            data.forEach(function(categoryItem) {
                var category = categoryItem.category;
                // gs.log("Processing category: " + category);

                if (categoryItem.actions && Array.isArray(categoryItem.actions)) {
                    categoryItem.actions.forEach(function(action) {
                        // Create the KPI object
                        var kpiObject = {
                            'category': category,
                            'kpi': action.type,
                            'description': action.description,
                            'short_description': action.short_description,
                            'instruction': action.instruction,
                            'plugins': action.plugins || [],
                            'properties': action.properties || []
                        };

                        // Push to the appropriate category array based on the category name
                        var categoryKey = category.toLowerCase().replace(/ /g, '_');
                        if (result[categoryKey]) {
                            result[categoryKey].push(kpiObject);
                        } else {
                            // If the category doesn't exist yet, create it
                            result[categoryKey] = [kpiObject];
                        }
                    });
                    // gs.log("Added " + categoryItem.actions.length + " actions from category " + category);
                }
            });
        }

        // gs.log("Total implementation KPIs processed across all categories");
    }

    // Try with corrected spelling first
    var implementationData = fetchKPIs(additionalKpiProperty);

    // If empty, try the original spelling as fallback
    if (!implementationData || implementationData.length === 0) {
        // gs.log("First property attempt failed, trying fallback property name");
        implementationData = fetchKPIs(fallbackPropertyName);
    }


    processImplementationKPIs(implementationData);
    // gs.log('data result returned'+JSON.stringify(result,null,2));
    return result;
}
